/**
 * Loads the shared 512x512 particle sprite sheet generated by
 * `npm run textures:particles` into `public/textures/particles.png` (spec 9.7).
 * One texture serves every particle VFX (the particle system, the orb glow and
 * the sprite billboards), so the sheet is loaded exactly once per page.
 */

import { SRGBColorSpace, Texture, TextureLoader } from 'three';

/** The particle sheet is loaded once and shared by every layer. */
let sheet: Texture | null = null;
let loadPromise: Promise<Texture | null> | null = null;

/** Loads (or returns the already loaded) particle sheet; null if the file is missing. */
export function loadParticleSheet(): Promise<Texture | null> {
  if (loadPromise !== null) {
    return loadPromise;
  }
  const loader = new TextureLoader();
  loadPromise = new Promise<Texture | null>((resolve) => {
    loader.load(
      `${import.meta.env.BASE_URL}textures/particles.png`,
      (texture) => {
        texture.colorSpace = SRGBColorSpace;
        texture.needsUpdate = true;
        sheet = texture;
        resolve(texture);
      },
      undefined,
      (error) => {
        console.error('vfx: failed to load textures/particles.png', error);
        resolve(null);
      },
    );
  });
  return loadPromise;
}

/** The already loaded sheet, or null while it is still loading. */
export function particleSheet(): Texture | null {
  return sheet;
}
